+	while (ptr > src_ && *(ptr - 1) <= ' ')
+		ptr--;
+	*ptr = '\0';
+	/* rewrite loop */
+	void *ret = NULL;
+	while (rewrite()) {
+		if (!--cycles) {
+			ret = "modal: rewrites exceeded";
+			break;
+		}
+	}
+	free(ms);
+	return ret;
+}
